import assert from 'node:assert/strict';
import { createController } from './src/controller.js';

const deferred = () => {
 let resolve, reject;
 const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
 return { promise, resolve, reject };
};

{
 const pending = deferred(), commits = [], audits = [], renders = [];
 const controller = createController({
  service: { commit(snapshot) { commits.push(snapshot); return pending.promise; } },
  audit: { record(entry) { audits.push(entry); } },
  render(view) { renders.push(view); }
 });
 controller.open('doc-a', 'actor-a'); controller.edit('first');
 const result = controller.submit();
